sp_widget.client_script:
api.controller = function() {
  var c = this;

  c.getStatusClass = function(status) {
    if (status === "open") return "label-warning";
    if (status === "pending") return "label-info";
    return "label-default";
  };
};

sp_widget.css:
.ibar-clarification-summary {
  padding: 20px;
}
.ibar-clarification-summary .section-title {
  margin-bottom: 16px;
  font-size: 16px;
  font-weight: 600;
}
.ibar-clarification-summary .clarification-item {
  padding: 10px 0;
  border-bottom: 1px solid #eee;
}
.ibar-clarification-summary .cl-header {
  margin-bottom: 4px;
}
.ibar-clarification-summary .cl-details span {
  margin-right: 16px;
  font-size: 12px;
  color: #666;
}

sp_widget.script:
(function() {
  data.clarifications = [];
  data.count = 0;

  try {
    var gr = new GlideRecord("x_1433041_identi_0_communication_thread");
    gr.addQuery("thread_type", "clarification");
    gr.addQuery("status", "IN", "open,pending");
    gr.orderByDesc("created_at");
    gr.setLimit(20);
    gr.query();

    data.count = gr.getRowCount();

    while (gr.next()) {
      var appName = "";
      var appGr = new GlideRecord("x_1433041_identi_0_application");
      if (appGr.get(gr.getValue("application"))) {
        appName = appGr.getValue("name");
      }
      var assignedName = "";
      if (gr.getValue("assigned_to")) {
        var userGr = new GlideRecord("sys_user");
        if (userGr.get(gr.getValue("assigned_to"))) {
          assignedName = userGr.getValue("name");
        }
      }
      var createdByName = "";
      if (gr.getValue("created_by")) {
        var creatorGr = new GlideRecord("sys_user");
        if (creatorGr.get(gr.getValue("created_by"))) {
          createdByName = creatorGr.getValue("name");
        }
      }
      data.clarifications.push({
        sys_id: gr.getUniqueValue(),
        application_name: appName,
        subject: gr.getValue("subject"),
        status: gr.getValue("status"),
        status_display: gr.getDisplayValue("status"),
        assigned_to_name: assignedName,
        created_by_name: createdByName,
        created_at: gr.getDisplayValue("created_at"),
        last_activity_at: gr.getDisplayValue("last_activity_at")
      });
    }
  } catch (e) {
    gs.error("IBAR Clarification Summary error: " + e.message);
  }
})();
